dtsPropsFor.Button:
/** Visual role. @default 'primary' */
  variant?: 'primary' | 'secondary' | 'danger';
  /** @default 'md' */
  size?: 'sm' | 'md' | 'lg';
  children?: React.ReactNode;
  disabled?: boolean;
  type?: 'button' | 'submit' | 'reset';
  onClick?: React.MouseEventHandler<HTMLButtonElement>;
  className?: string;

dtsPropsFor.DataTable:
/** Column headings, in visual order. */
  headers: string[];
  /** The <tr> rows. Style cells with `px-4 py-3`. */
  children: React.ReactNode;
  /** Rendered instead of the table when isEmpty is true. */
  emptyState?: React.ReactNode;
  isEmpty?: boolean;

dtsPropsFor.EmptyState:
title: string;
  description?: string;
  /** Usually a <Button>. */
  action?: React.ReactNode;

dtsPropsFor.Input:
/** Renders a <label> bound to the input. */
  label?: string;
  /** Red border + message below. */
  error?: string;
  placeholder?: string;
  type?: string;
  value?: string | number;
  defaultValue?: string | number;
  disabled?: boolean;
  onChange?: React.ChangeEventHandler<HTMLInputElement>;
  className?: string;

dtsPropsFor.Select:
label?: string;
  error?: string;
  /** Required. Rendered as <option>s. */
  options: { value: string; label: string }[];
  /** Disabled first option shown when value is ''. */
  placeholder?: string;
  value?: string;
  defaultValue?: string;
  disabled?: boolean;
  onChange?: React.ChangeEventHandler<HTMLSelectElement>;
  className?: string;

dtsPropsFor.Textarea:
label?: string;
  error?: string;
  placeholder?: string;
  /** @default 3 */
  rows?: number;
  value?: string;
  defaultValue?: string;
  disabled?: boolean;
  onChange?: React.ChangeEventHandler<HTMLTextAreaElement>;
  className?: string;

dtsPropsFor.Modal:
/** Renders nothing when false. */
  open: boolean;
  /** Fired by the backdrop click and the Escape key. */
  onClose: () => void;
  title: string;
  children: React.ReactNode;
